 const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.glass}</svg>`;
 let db,storageError='',env={data:C.validate(C.clone(window.MIX_SEED)),base:null,syncId:'',sha:null,lastSync:null},view='recipes',filters={q:'',tags:[],sourceName:'',availability:'all',favorite:false},sort='default',pantryQ='',onlyOwned=false,filterOpen=false,syncBusy=false,saveTimer=null,toastTimer=null,editorId=null,lastFocus=null;
 let pantryDraft=null,editorDraft=null,editorMode='recipe',editorVersion='',selectedVersion='',itemContext='',itemId='';
 let pantryBrowser=null,pickerBrowser=null,itemReturn=null;const dialogFocus=new WeakMap();
 const editing=()=>!!pantryDraft||!!$('#editor-dialog')?.open||!!$('#item-dialog')?.open||!!$('#material-dialog')?.open;
