 try{config={...config,...JSON.parse(localStorage.getItem('mixbook.config')||'{}')};token=sessionStorage.getItem('mixbook.token')||localStorage.getItem('mixbook.token')||'';remember=!!localStorage.getItem('mixbook.token')}catch{}
 try{
   db=await new Promise((resolve,reject)=>{const req=indexedDB.open('mixbook',1);req.onupgradeneeded=()=>req.result.createObjectStore('state');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});
   const loaded=await dbRead('current');if(loaded){if(loaded.data.schemaVersion<3)await dbWrite('backup-before-v3',loaded);env={...env,...loaded,data:C.installCatalog(loaded.data,window.MIX_SEED)};if(env.base)env.base=C.installCatalog(env.base,window.MIX_SEED)}await dbWrite('current',env);
 }catch{storageError='浏览器未能读取本地数据。当前为临时会话，请先导出备份；不要清理浏览器数据。';db=null}
 function dbRead(key){return new Promise((resolve,reject)=>{const tx=db.transaction('state','readonly'),req=tx.objectStore('state').get(key);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
 function dbWrite(key,value){return new Promise((resolve,reject)=>{const tx=db.transaction('state','readwrite');tx.objectStore('state').put(value,key);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
 let writeQueue=Promise.resolve();
 async function persist(next){if(db)await dbWrite('current',next);env=next}
 function update(change){if(syncBusy){toast('正在同步，请稍后再修改。');return Promise.resolve(false)};const task=writeQueue.then(async()=>{const next=C.clone(env);change(next.data);next.data=C.validate(next.data);await persist(next);scheduleSync();return true}).catch(e=>{toast('保存失败：'+e.message);return false});writeQueue=task;return task}
 function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4200)}
 function dirty(){return !env.base||!C.same(env.data,env.base)}
 function status(){return syncBusy?'正在同步…':storageError?'临时会话':config.repo&&env.lastSync?(dirty()?'有待同步修改':'已同步'):'已存本机'}
 function dateText(v){return v?new Date(v).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}):'尚未同步'}
